{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyon-threshold.pagewell.app/incident-readiness-kit/schema/incident-report.schema.json",
  "title": "Halcyon Threshold Incident Report",
  "description": "Experimental incident-report format v0.1.0. Not a regulatory standard. Exercises must use report_type=test.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "report_id",
    "status",
    "report_type",
    "created_at",
    "updated_at",
    "supersedes",
    "reporter",
    "system",
    "summary",
    "impact",
    "current_state",
    "decision",
    "unknowns",
    "evidence",
    "actions",
    "confidentiality",
    "extensions"
  ],
  "properties": {
    "schema_version": { "const": "0.1.0" },
    "report_id": {
      "type": "string",
      "pattern": "^IR-[A-Z0-9-]{3,64}$"
    },
    "status": { "enum": ["draft", "initial", "update", "final"] },
    "report_type": { "enum": ["incident", "near_miss", "hazard", "test"] },
    "created_at": { "$ref": "#/$defs/timestamp" },
    "updated_at": { "$ref": "#/$defs/timestamp" },
    "supersedes": {
      "anyOf": [
        { "type": "string", "pattern": "^IR-[A-Z0-9-]{3,64}$" },
        { "type": "null" }
      ]
    },
    "reporter": {
      "type": "object",
      "additionalProperties": false,
      "required": ["role", "contact_channel"],
      "properties": {
        "role": { "$ref": "#/$defs/nonEmptyString" },
        "contact_channel": { "$ref": "#/$defs/nonEmptyString" }
      }
    },
    "system": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name", "version", "deployment_context", "autonomy_level", "affected_component"],
      "properties": {
        "name": { "$ref": "#/$defs/nonEmptyString" },
        "version": { "$ref": "#/$defs/nonEmptyString" },
        "deployment_context": { "$ref": "#/$defs/nonEmptyString" },
        "autonomy_level": {
          "enum": ["no_tool_use", "supervised_tools", "bounded_agent", "broad_agent", "other", "unknown"]
        },
        "affected_component": { "$ref": "#/$defs/nonEmptyString" }
      }
    },
    "summary": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "what_happened",
        "why_it_matters",
        "detected_at",
        "started_at",
        "ended_at",
        "detection_method",
        "safety_properties_failed"
      ],
      "properties": {
        "what_happened": { "$ref": "#/$defs/nonEmptyString" },
        "why_it_matters": { "$ref": "#/$defs/nonEmptyString" },
        "detected_at": { "$ref": "#/$defs/nullableTimestamp" },
        "started_at": { "$ref": "#/$defs/nullableTimestamp" },
        "ended_at": { "$ref": "#/$defs/nullableTimestamp" },
        "detection_method": { "$ref": "#/$defs/nonEmptyString" },
        "safety_properties_failed": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["statement", "assessment_basis"],
            "properties": {
              "statement": { "$ref": "#/$defs/nonEmptyString" },
              "assessment_basis": { "enum": ["observed", "inferred", "unknown"] }
            }
          }
        }
      }
    },
    "impact": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "actual",
        "potential",
        "actual_basis",
        "potential_pathway",
        "affected_parties",
        "scope",
        "impact_evidence_refs"
      ],
      "properties": {
        "actual": { "enum": ["none", "minor", "serious", "catastrophic", "unknown"] },
        "potential": { "enum": ["none", "minor", "serious", "catastrophic", "unknown"] },
        "actual_basis": { "$ref": "#/$defs/nonEmptyString" },
        "potential_pathway": { "$ref": "#/$defs/nonEmptyString" },
        "affected_parties": {
          "type": "array",
          "items": { "$ref": "#/$defs/nonEmptyString" }
        },
        "scope": { "$ref": "#/$defs/nonEmptyString" },
        "impact_evidence_refs": {
          "type": "array",
          "items": { "type": "string" },
          "uniqueItems": true
        }
      }
    },
    "current_state": {
      "type": "object",
      "additionalProperties": false,
      "required": ["ongoing", "containment_status", "containment_actions", "state_basis"],
      "properties": {
        "ongoing": { "type": "boolean" },
        "containment_status": {
          "enum": ["not_contained", "partially_contained", "contained", "not_applicable", "unknown"]
        },
        "containment_actions": {
          "type": "array",
          "items": { "$ref": "#/$defs/nonEmptyString" }
        },
        "state_basis": { "$ref": "#/$defs/nonEmptyString" }
      }
    },
    "decision": {
      "type": "object",
      "additionalProperties": false,
      "required": ["owner_role", "escalation_needed", "next_update_at", "external_deadline_at", "deadline_basis"],
      "properties": {
        "owner_role": { "$ref": "#/$defs/nonEmptyString" },
        "escalation_needed": { "type": "boolean" },
        "next_update_at": { "$ref": "#/$defs/nullableTimestamp" },
        "external_deadline_at": { "$ref": "#/$defs/nullableTimestamp" },
        "deadline_basis": { "type": "string" }
      }
    },
    "unknowns": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["question", "why_it_matters", "owner_role", "due_at"],
        "properties": {
          "question": { "$ref": "#/$defs/nonEmptyString" },
          "why_it_matters": { "$ref": "#/$defs/nonEmptyString" },
          "owner_role": { "type": ["string", "null"] },
          "due_at": { "$ref": "#/$defs/nullableTimestamp" }
        }
      }
    },
    "evidence": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["ref", "description", "location_or_handle", "collected_at", "integrity_notes", "access"],
        "properties": {
          "ref": { "$ref": "#/$defs/nonEmptyString" },
          "description": { "$ref": "#/$defs/nonEmptyString" },
          "location_or_handle": { "$ref": "#/$defs/nonEmptyString" },
          "collected_at": { "$ref": "#/$defs/nullableTimestamp" },
          "integrity_notes": { "$ref": "#/$defs/nonEmptyString" },
          "access": { "enum": ["restricted", "internal", "public"] }
        }
      }
    },
    "actions": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["action_id", "description", "owner_role", "due_at", "status"],
        "properties": {
          "action_id": { "$ref": "#/$defs/nonEmptyString" },
          "description": { "$ref": "#/$defs/nonEmptyString" },
          "owner_role": { "$ref": "#/$defs/nonEmptyString" },
          "due_at": { "$ref": "#/$defs/nullableTimestamp" },
          "status": { "enum": ["proposed", "in_progress", "done", "blocked"] }
        }
      }
    },
    "root_causes": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["statement", "status", "evidence_refs"],
        "properties": {
          "statement": { "$ref": "#/$defs/nonEmptyString" },
          "status": { "enum": ["confirmed", "hypothesis"] },
          "evidence_refs": {
            "type": "array",
            "items": { "type": "string" },
            "uniqueItems": true
          }
        }
      }
    },
    "preventive_actions": {
      "type": "array",
      "items": { "type": "string" },
      "uniqueItems": true
    },
    "confidentiality": { "enum": ["restricted", "internal", "public"] },
    "extensions": { "type": "object" }
  },
  "allOf": [
    {
      "if": {
        "properties": { "status": { "const": "final" } },
        "required": ["status"]
      },
      "then": {
        "properties": {
          "summary": {
            "properties": { "ended_at": { "$ref": "#/$defs/timestamp" } },
            "required": ["ended_at"]
          },
          "current_state": {
            "properties": {
              "ongoing": { "const": false },
              "containment_status": { "enum": ["contained", "not_applicable"] }
            },
            "required": ["ongoing", "containment_status"]
          }
        }
      }
    },
    {
      "if": {
        "properties": { "external_deadline_at": { "type": "string" } },
        "required": ["external_deadline_at"]
      },
      "then": {
        "properties": { "deadline_basis": { "type": "string", "minLength": 1 } }
      }
    },
    {
      "if": {
        "properties": { "report_type": { "const": "test" } },
        "required": ["report_type"]
      },
      "then": {
        "properties": {
          "impact": {
            "properties": { "actual": { "const": "none" } },
            "required": ["actual"]
          }
        }
      }
    }
  ],
  "$defs": {
    "nonEmptyString": { "type": "string", "minLength": 1 },
    "timestamp": { "type": "string", "format": "date-time" },
    "nullableTimestamp": {
      "anyOf": [
        { "$ref": "#/$defs/timestamp" },
        { "type": "null" }
      ]
    }
  }
}

